header = lines[0].split()
height = int(header[1])
comment_lines = int(header[5])
def get_char(c):
    idx = ord(c) - 32
    start = 1 + comment_lines + idx * height
    return '\n'.join(lines[start:start+height])
for char in 'ThefirstinComfortExcellenceStyle':
    print(f'--- {char} ---\n{get_char(char)}')"}

